"""GELU MLP dispatch."""

import torch
import torch.nn.functional as F

from kestrel_kernels._pybridge import fused_mlp_gelu_bias_residual as _raw


def _gelu_approx_code(approximate: str) -> int:
    if approximate == "tanh":
        return 1
    if approximate == "none":
        return 0
    raise ValueError(f"unsupported GELU approximation: {approximate!r}")


def fused_mlp_gelu_bias_residual_cuda(
    out,
    hidden,
    x,
    w1,
    b1,
    w2,
    b2,
    residual,
    *,
    approximate: str = "tanh",
):
    dtype_code = 0 if x.dtype == torch.bfloat16 else 1
    _raw(
        out,
        hidden,
        x,
        w1,
        b1,
        w2,
        b2,
        residual,
        dtype_code,
        _gelu_approx_code(approximate),
    )


_HIDDEN_WORKSPACES: dict[
    tuple[int, torch.dtype, int, int], list[torch.Tensor]
] = {}


def _is_aligned(tensor: torch.Tensor) -> bool:
    return tensor.data_ptr() % 16 == 0


def _hidden_workspace(
    rows: int,
    hidden_dim: int,
    *,
    device: torch.device,
    dtype: torch.dtype,
) -> torch.Tensor:
    stream = torch.cuda.current_stream(device)
    device_index = device.index
    if device_index is None:
        device_index = torch.cuda.current_device()
    key = (device_index, dtype, hidden_dim, stream.cuda_stream)
    workspaces = _HIDDEN_WORKSPACES.setdefault(key, [])
    for workspace in workspaces:
        if workspace.shape[0] >= rows:
            return workspace[:rows]
    workspace = torch.empty((rows, hidden_dim), device=device, dtype=dtype)
    # Retain smaller allocations: a captured graph may still replay against
    # their stable pointers after a larger shape is seen on this stream.
    workspaces.append(workspace)
    return workspace[:rows]


def mlp_gelu_bias_residual(
    x: torch.Tensor,
    w1: torch.Tensor,
    b1: torch.Tensor,
    w2: torch.Tensor,
    b2: torch.Tensor,
    residual: torch.Tensor,
    *,
    approximate: str = "tanh",
) -> torch.Tensor:
    """Return ``residual + linear(gelu(linear(x)))`` on every backend.

    CUDA uses the cuBLASLt fused implementation when its tensor contract is
    satisfied. Workspace ownership and capability selection stay here so
    model code does not need device or dtype branches.
    """
    _gelu_approx_code(approximate)
    if x.ndim not in (2, 3):
        raise ValueError(f"x must be 2D or 3D, got {tuple(x.shape)}")
    if residual.shape[:-1] != x.shape[:-1] or residual.shape[-1] != w2.shape[0]:
        raise ValueError(
            "residual must match x's row dimensions and w2's output dimension, "
            f"got x={tuple(x.shape)}, w2={tuple(w2.shape)}, "
            f"residual={tuple(residual.shape)}"
        )

    parameters = (w1, b1, w2, b2)
    supported = (
        x.is_cuda
        and x.dtype in (torch.bfloat16, torch.float16)
        and residual.device == x.device
        and residual.dtype == x.dtype
        and all(
            tensor.device == x.device
            and tensor.dtype == x.dtype
            and tensor.is_contiguous()
            and _is_aligned(tensor)
            for tensor in parameters
        )
        and w1.ndim == 2
        and b1.shape == (w1.shape[0],)
        and w1.shape[1] == x.shape[-1]
        and w2.ndim == 2
        and w2.shape[1] == w1.shape[0]
        and b2.shape == (w2.shape[0],)
    )
    if supported:
        x2 = x.reshape(-1, x.shape[-1]).contiguous()
        residual2 = residual.reshape(-1, residual.shape[-1]).contiguous()
        supported = _is_aligned(x2) and _is_aligned(residual2)
    if not supported:
        hidden = F.gelu(F.linear(x, w1, b1), approximate=approximate)
        return residual + F.linear(hidden, w2, b2)

    out2 = torch.empty_like(residual2)
    hidden = _hidden_workspace(x2.shape[0], w1.shape[0], device=x.device, dtype=x.dtype)
    fused_mlp_gelu_bias_residual_cuda(
        out2,
        hidden,
        x2,
        w1,
        b1,
        w2,
        b2,
        residual2,
        approximate=approximate,
    )
    return out2.reshape(residual.shape)


__all__ = [
    "fused_mlp_gelu_bias_residual_cuda",
    "mlp_gelu_bias_residual",
]
